 /// For a page-aligned address `a`, dividing by the page size then multiplying recovers `a`.
 pub proof fn lemma_aligned_addr_index(a: int)
     requires
         a % spec_page_size() == 0,
         spec_page_size() > 0,
     ensures
         frame_addr_of(a / spec_page_size()) == a,
