         },
 {
     let i = addr / spec_page_size();
     lemma_aligned_addr_index(addr);
     if inner@.free_frames.contains(addr) {
         let j = choose|j: int|
             0 <= j < inner.bitmap@.num_bits && !(#[trigger] inner.bitmap@.set_bits.contains(j))
